// The resident list lives in the kitchen's door_state.json and in this computer's saved copy, never in this page
// (2026-10-31). The page is served publicly on GitHub Pages, and it used to carry April's list as a built-in fallback:
// a new computer with no internet showed that list, flags and all. A computer with no saved list now starts empty
// and says so (doorNoResidentListNoticeHTML) until it gets the kitchen's list.
const REGISTRY_LIST = [];

// A new computer starts with an empty log and takes the kitchen's recent_log.json at its first sync (2026-10-31).
// The first-run sample used to invent eight changes on real room numbers. They carried no _real:false mark, so
// they read as real here and went out with this computer's next publish.
return [];

// A computer with no resident list says so on its plating sheet, in red and in print, rather than showing a sheet
// with no residents that reads as finished (2026-10-31, when the built-in list left this page).
function doorNoResidentListNoticeHTML() {
  if (REGISTRY_LIST.length) return '';
  return '<div class="door-no-resident-list" role="alert" style="margin:0 0 12px;padding:10px 14px;border:2px solid #dc2626;border-radius:6px;background:#fef2f2;color:#991b1b;font-weight:600;font-size:13px;">' +
    'No resident list on this computer — these sheets show no residents. Press ↻ Refresh list on Enter Changes when online, or ↑ Import Daily List.</div>';
}
